"""V0.6.0 — UI real (Playwright/Chromium) de los cinco espacios. Servidor local REAL con proveedores SIMULADOS (sin red, sin Keepa/OpenAI/Amazon reales). Genera capturas en CAPTURAS_UI/."""
import os, sys, tempfile, threading
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path.insert(0, ROOT); os.environ["AMAZON_PRO_NO_WORKER"] = "1"
from playwright.sync_api import sync_playwright
import server as S
from backend import ai as AI
OUT = os.path.join(ROOT, "CAPTURAS_UI"); os.makedirs(OUT, exist_ok=True); R = []
def check(n, c): R.append(bool(c)); print(("OK   " if c else "FAIL ") + n)
tmp = tempfile.mkdtemp(); csvp = os.path.join(tmp, "ventas.csv")
open(csvp, "w", encoding="utf-8").write("Fecha;ASIN;Ventas de productos pedidos;Unidades pedidas;Sesiones - total\n2026-10-01;B0F6KQP2WH;120,50 €;8;100\n2026-10-02;B0F6KQP2WH;80,00 €;5;60\n2026-10-03;B0F6KQP2WH;95,00 €;6;80\n")
srv = S.make_server(0, admin_token="t", db_path=os.path.join(tmp, "s.db"), cfg_fn=lambda: AI.config({}), admin_password="admin-password-123"); port = srv.server_address[1]
threading.Thread(target=srv.serve_forever, daemon=True).start()
