    t = pg.inner_text("#v6inicio"); check("INICIO en prelanzamiento: muestra preparación, no ventas inventadas", "PRELANZAMIENTO" in t and "Ventas importadas" not in t and "Fichas completas" in t)
    check("4 gráficos con su pregunta de negocio", all(q in t for q in ["¿Cuánto vendo y cuánto gano?", "¿Cómo estoy de precio frente a la competencia?", "¿Qué retorno me da la publicidad?", "¿Dónde estoy posicionado"]))
    check("cada gráfico declara fuente, periodo, actualización y estado", pg.locator(".v6foot").count() == 4 and all(k in t for k in ["Fuente:", "Periodo:", "Actualizado:"]))
    check("estados honestos: SIN DATOS y PENDIENTE DE CONEXIÓN", "SIN DATOS" in t and "PENDIENTE DE CONEXIÓN" in t)
    check("Director IA destacado a la derecha con bandeja de decisiones", pg.locator(".v6dir").count() == 1 and "Bandeja de decisiones" in t)
    check("diseño NEON: fondo oscuro y bordes de color", pg.evaluate("getComputedStyle(document.body).backgroundColor") in ("rgb(2, 5, 13)",) and pg.locator(".card.c-cyan").count() >= 1)
    pg.screenshot(path=f"{OUT}/20_inicio_prelanzamiento.png")
    pg.click("[data-act=demo-on]"); pg.wait_for_selector(".v6demo"); pg.wait_for_selector("#dm-ventas svg")
    check("DEMO: aviso permanente, rotulado SINTÉTICO y 4 gráficos", "DATOS SINTÉTICOS" in pg.inner_text(".v6demo") and pg.locator(".v6isdemo svg").count() >= 4 and "SINTÉTICO" in pg.inner_text(".v6isdemo"))
    pg.screenshot(path=f"{OUT}/21_inicio_demo.png"); pg.click("[data-act=demo-off]"); pg.wait_for_selector(".v6demo", state="detached"); pg.wait_for_selector("#v6Prod-inicio")
    check("salir de DEMO elimina todo dato sintético", "SINTÉTICO" not in pg.inner_text("#v6inicio") and pg.locator(".v6demo").count() == 0)
    pg.select_option("#v6Prod-inicio", "PRD-ACTIVCORE-V2"); pg.wait_for_selector("[data-act=order]:not([disabled])"); pg.click("[data-act=order]"); pg.wait_for_selector(".v6dec"); pg.wait_for_timeout(500)
    t = pg.inner_text("#v6inicio"); check("orden al Director: trabajo automático hecho + 1 decisión crítica esperando", "COMPLETADA" in t and "llamada_keepa_nueva" in t or "competidores reales" in t)
    check("la aprobación Keepa NO se concede sola (sin gasto)", pg.locator(".v6dec").count() == 1)
    pg.screenshot(path=f"{OUT}/22_inicio_orden_director.png")
    pg.click("#tabs button[data-tab=lanz]"); pg.wait_for_selector(".v6sec"); pg.wait_for_timeout(400)
    check("LANZAMIENTOS: expediente de 11 secciones y descargas MD/HTML", pg.locator(".v6sec").count() == 11 and pg.locator("a[download]").count() == 2)
    t = pg.inner_text("#v6lanz"); check("expediente: NO DECIDIBLE, NL/PL pendientes de conexión, UK separado, borradores marcados", "NO DECIDIBLE" in t and "Países Bajos" in t and "SEPARADO" in t and "BORRADOR" in t)
    pg.screenshot(path=f"{OUT}/23_lanzamientos.png", full_page=True)
    pg.click("#tabs button[data-tab=ventas]"); pg.wait_for_selector("#v6File"); pg.select_option("#v6Prod-ventas", "PRD-PHIVITAL-MAGNESIO"); pg.wait_for_timeout(1200); pg.wait_for_selector("#v6File")
    check("MIS VENTAS sin datos: SIN DATOS (no ceros)", "SIN DATOS" in pg.inner_text("#v6ventas") and "importa un informe" in pg.inner_text("#v6ventas").lower())
