    check("rentabilidad: NO CALCULABLE y dice qué costes faltan (sin defaults)", "NO CALCULABLE" in t and "falta:" in t)
    pg.click("[data-act=inv]"); check("inventario sin hipótesis: NO DETERMINABLE", "NO DETERMINABLE" in pg.inner_text("#v6InvOut"))
    check("tabla de conexiones: Amazon PENDIENTE DE CONEXIÓN y Keepa NO VERIFICADO", "PENDIENTE DE CONEXIÓN" in pg.inner_text("#v6ventas") and "NO VERIFICADO" in pg.inner_text("#v6ventas"))
