    check("INICIO con ventas importadas: modo OPERACIÓN, gráfico real y publicidad aún SIN DATOS", "OPERACIÓN" in t and "Ventas importadas" in t and pg.locator("#ch-ventas svg").count() == 1 and "Sin informe de publicidad" in t)
    pg.screenshot(path=f"{OUT}/25_inicio_operacion.png")
    pg.click("#tabs button[data-tab=prod]"); pg.wait_for_selector(".v6prod"); t = pg.inner_text("#v6prod")
    check("PRODUCTOS: catálogo por categorías con ACTIVCORE, PHIVITAL Magnesio y Omega-3", all(x in t for x in ["ACTIVCORE V2", "PHIVITAL Magnesio", "PHIVITAL Omega-3", "Cosmética", "Suplementos"]))
    pg.click("[data-act=new]"); pg.fill("#fpName", "Sérum de prueba"); pg.fill("#fpBrand", "AHT"); pg.fill("#fpSku", "AHT-T1"); pg.fill("#fpCont", "50"); pg.fill("#fpComp", "Cafeína\nUrea"); pg.fill("#fpClaims", "Detiene la caída del cabello"); pg.click("[data-act=save]"); pg.wait_for_selector("text=Producto creado"); pg.wait_for_timeout(400)
    check("alta de producto sin programar + arranque automático del expediente", "Sérum de prueba" in pg.inner_text("#v6prod") and "arrancado su expediente" in pg.inner_text("#v6prod"))
    pg.screenshot(path=f"{OUT}/26_productos.png", full_page=True)
    pg.click("#tabs button[data-tab=dir]"); pg.wait_for_selector("text=Cola de tareas"); pg.wait_for_timeout(500); t = pg.inner_text("#v6dir")
    check("DIRECTOR IA: cola con prioridad explicada, autonomía N1–N4, modelos y libro", all(x in t for x in ["Cola de tareas", "N1", "N4", "Modelos de IA", "Libro de decisiones", "NO DIMENSIONADO"]))
    pg.once("dialog", lambda d: d.accept()); pg.click("[data-act=kill]"); pg.wait_for_selector("text=INTERRUPTOR DE EMERGENCIA ACTIVO"); check("interruptor de emergencia activable desde la UI", True)
    pg.screenshot(path=f"{OUT}/27_director_ia.png", full_page=True); pg.click("[data-act=kill]"); pg.wait_for_selector("text=Automatizaciones externas permitidas")
    pg.click("#tabs button[data-tab=panel]"); pg.wait_for_selector("#kpis .kpi"); check("Panel DEMO antiguo sigue accesible bajo «Avanzado» y rotulado DEMO", "DEMO" in pg.inner_text("#badge"))
    check("sin errores JS ni violaciones CSP", not errs)
    m = b.new_context(viewport={"width": 390, "height": 844}).new_page(); m.goto(f"http://localhost:{port}/?legacy=1"); m.wait_for_selector("#tabs"); m.fill  # noqa
    m.click("#lgOpen"); m.fill("#lgU", "admin"); m.fill("#lgP", "admin-password-123"); m.click("#lgGo"); m.wait_for_selector(".sessu"); m.wait_for_selector("#v6inicio .kpi"); m.wait_for_timeout(500)
    check("móvil 390 px: sin desbordamiento horizontal", m.evaluate("document.documentElement.scrollWidth") <= 392); m.screenshot(path=f"{OUT}/28_movil_inicio.png", full_page=True)
